import base64
import hashlib
import io
import json
import requests
from pydantic import BaseModel, Field

try:
    from PIL import Image

    _PIL_AVAILABLE = True
except ImportError:
    _PIL_AVAILABLE = False


class Filter:
    class Valves(BaseModel):
        OLLAMA_BASE_URL: str = Field(
            default="http://<GAMING_PC_IP>:11434",
            description="IP address and port of your gaming PC running Ollama",
        )
        VISION_MODEL: str = Field(
            default="minicpm-v:latest",
            description="Vision model used to convert images to text for the main model",
        )
        CAPTION_PROMPT: str = Field(
            default=(
                "You are an expert visual analysis system. Analyze the image and return "
                "a JSON object with these exact keys:\n"
                "{\n"
                '  "description": "A clear, concise overall description of what the image shows",\n'
                '  "visible_text": ["Every distinct piece of text visible in the image, verbatim - '
                'labels, headers, captions, UI text, signage, HUD elements"],\n'
                '  "notable_objects_or_subjects": ["The key objects, people, or subjects present"],\n'
                '  "other_details": "Layout, colors, context, mood, or other notable characteristics"\n'
                "}\n"
                "If the image is a screenshot of a game, application, or webpage, include on-screen "
                "UI elements, status indicators, and interactable prompts in the relevant fields."
            ),
            description="The JSON extraction prompt sent to the vision model",
        )
        MAX_IMAGE_DIMENSION: int = Field(
            default=1024,
            description="Resize images so their longest side is at most this many pixels before "
            "sending to the vision model (0 to disable resizing). Most vision models downsample "
            "internally anyway, so sending full-resolution screenshots is usually wasted bandwidth.",
        )
        OLLAMA_TIMEOUT: int = Field(
            default=60,
            description="Timeout in seconds for each vision model request",
        )
        SHOW_ERRORS_TO_MODEL: bool = Field(
            default=True,
            description="When an image fails to analyze, tell the main model an image was present "
            "but couldn't be analyzed (rather than silently dropping it or blending the raw error "
            "text into what looks like real visual data)",
        )

    def __init__(self):
        self.valves = self.Valves()
        # persists for the life of this Filter instance, so identical
        # images across turns (e.g. an older message still holding raw
        # image data that gets re-scanned every turn) don't trigger a
        # fresh vision-model call each time - only helps if Open-WebUI
        # reuses the same instance across turns of a conversation, which
        # is likely but unconfirmed; harmless either way if it doesn't
        self._image_cache = {}

    # -----------------------------------------------------------------
    # Message parsing
    # -----------------------------------------------------------------
    def _extract_content_parts(self, message: dict):
        """Returns (text, list_of_image_data). Handles both the modern
        list-of-content-parts structure and the legacy top-level 'images' key."""
        raw_content = message.get("content", "")
        text = ""
        images = []

        if isinstance(raw_content, list):
            for item in raw_content:
                if isinstance(item, dict):
                    if item.get("type") == "text":
                        text += item.get("text", "") + " "
                    elif item.get("type") == "image_url":
                        url = item.get("image_url", {}).get("url", "")
                        if url:
                            images.append(url)
                elif isinstance(item, str):
                    text += item + " "
        else:
            text = str(raw_content)

        legacy_images = message.pop("images", [])
        for img in legacy_images:
            if isinstance(img, str):
                images.append(img)
            elif isinstance(img, dict) and "url" in img:
                images.append(img["url"])

        return text.strip(), images

    # -----------------------------------------------------------------
    # Image handling
    # -----------------------------------------------------------------
    def _resize_image_b64(self, base64_str: str) -> str:
        """Downscale before sending to the vision model - most models
        internally downsample anyway, so a full-res screenshot is usually
        wasted upload/preprocessing time. Falls back to the original
        string untouched if Pillow isn't installed or decoding fails -
        never blocks captioning over a resize failure."""
        if not _PIL_AVAILABLE or self.valves.MAX_IMAGE_DIMENSION <= 0:
            return base64_str
        try:
            raw = base64.b64decode(base64_str)
            img = Image.open(io.BytesIO(raw))
            w, h = img.size
            if max(w, h) <= self.valves.MAX_IMAGE_DIMENSION:
                return base64_str
            scale = self.valves.MAX_IMAGE_DIMENSION / max(w, h)
            img = img.resize((max(1, int(w * scale)), max(1, int(h * scale))))
            buf = io.BytesIO()
            img.save(buf, format=img.format or "PNG")
            return base64.b64encode(buf.getvalue()).decode("utf-8")
        except Exception:
            return base64_str

    def _caption_image(self, img_data, cache: dict):
        """Returns (caption_or_None, error_or_None). Never raises - all
        failure modes are converted into a clear, separate error string
        instead of being blended into the caption text itself."""
        base64_str = str(img_data)
        stripped = base64_str.strip()

        if stripped.lower().startswith("data:") and "," in base64_str:
            base64_str = base64_str.split(",", 1)[1]
        elif stripped.lower().startswith("http"):
            # external URL, not embedded base64 - Ollama's /api/generate
            # expects raw image bytes here, not a URL, so sending this
            # through would silently fail server-side
            return (
                None,
                "image was referenced by external URL rather than embedded data - skipped",
            )

        cache_key = hashlib.sha256(
            base64_str.encode("utf-8", errors="ignore")
        ).hexdigest()
        if cache_key in cache:
            return cache[cache_key], None

        resized = self._resize_image_b64(base64_str)

        payload = {
            "model": self.valves.VISION_MODEL,
            "prompt": self.valves.CAPTION_PROMPT,
            "images": [resized],
            "format": "json",
            "stream": False,
        }

        try:
            url = f"{self.valves.OLLAMA_BASE_URL.rstrip('/')}/api/generate"
            response = requests.post(
                url, json=payload, timeout=self.valves.OLLAMA_TIMEOUT
            )
            response.raise_for_status()
            result = response.json()
            raw_caption = result.get("response", "").strip()
        except Exception as e:
            return None, f"{type(e).__name__}: {e}"

        if not raw_caption:
            return None, "vision model returned an empty response"

        # validate/normalize the JSON - format="json" doesn't guarantee
        # well-formed output, especially from a smaller model on a fairly
        # detailed 4-key schema
        try:
            parsed = json.loads(raw_caption)
            caption = json.dumps(parsed, ensure_ascii=False)
        except (json.JSONDecodeError, ValueError):
            # not valid JSON - still usable as text, but flagged so the
            # model (and you, if you inspect it) knows it wasn't clean
            caption = f"[unstructured - vision model did not return valid JSON]\n{raw_caption}"

        cache[cache_key] = caption
        return caption, None

    # -----------------------------------------------------------------
    # Main pipeline
    # -----------------------------------------------------------------
    async def inlet(
        self, body: dict, __event_emitter__=None, __user__: dict = None
    ) -> dict:
        messages = body.get("messages", [])
        if not messages:
            return body

        cache = self._image_cache
        processed_any = False

        for message in messages:
            text, images = self._extract_content_parts(message)

            if not images:
                # normalize any list-of-parts content down to plain text
                # even when there was nothing to caption, so the main
                # model never sees the raw content-parts structure
                if isinstance(message.get("content"), list):
                    message["content"] = text
                continue

            processed_any = True
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": f"Analyzing {len(images)} image(s)...",
                            "done": False,
                        },
                    }
                )

            captions, errors = [], []
            for img in images:
                caption, err = self._caption_image(img, cache)
                if caption:
                    captions.append(caption)
                elif err:
                    errors.append(err)

            parts = []
            if captions:
                grounding_rule = (
                    "SYSTEM INSTRUCTION / STRICT GROUNDING RULE:\n"
                    "You are answering questions about attached image(s) based ONLY on the "
                    "structured visual metadata below.\n"
                    "- Do NOT hallucinate, invent, or assume objects, text, or details that are "
                    "not explicitly listed in the visual metadata.\n"
                    "- Base your answer directly on the reported description, visible text, and "
                    "notable objects/subjects."
                )
                parts.append(grounding_rule)
                parts.append(f"User Message: {text}")
                parts.append(
                    "Structured Visual Metadata (JSON):\n" + "\n\n".join(captions)
                )
            else:
                parts.append(text)

            if errors and self.valves.SHOW_ERRORS_TO_MODEL:
                parts.append(
                    f"[Note: {len(errors)} attached image(s) could not be analyzed due to a "
                    f"technical error and are NOT described above - do not guess their contents.]"
                )

            message["content"] = "\n\n".join(p for p in parts if p)
            message.pop("files", None)

        if "files" in body:
            body["files"] = [
                f
                for f in body.get("files", [])
                if not (isinstance(f, dict) and f.get("type", "").startswith("image"))
            ]

        if processed_any and __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {"description": "Image analysis complete", "done": True},
                }
            )

        return body
